<template>
  <div class="idmp-page sql-import-page">
    <PageHeader title="SQL 导入因子/指标"><template #actions><el-button v-if="canStartNewImport" type="primary" plain @click="startNewImport">开始新的导入</el-button><el-button :icon="ArrowLeft" @click="router.push('/indicator')">返回指标目录</el-button></template></PageHeader>
    <section class="surface-card section"><div class="section-heading"><div><h2>1. 提交并解析 SQL</h2><span>创建导入会话后，系统只解析，不创建资源。</span></div><el-button type="primary" :loading="createLoading" :disabled="Boolean(importTask?.importId) || !sql.trim()" @click="createImport">解析 SQL</el-button></div><el-input v-model="sql" type="textarea" :rows="13" class="sql-editor" placeholder="请输入 MySQL 8 SELECT SQL" /><el-alert class="sql-parameter-hint" type="info" :closable="false" show-icon><template #title>业务参数必须使用可选条件模板，例如 <code v-text="'[[AND b.In_Dept_Code = {{deptCode}}]]'" />；不支持 <code>:deptCode</code>。</template></el-alert></section>

    <section v-if="importTask" class="surface-card section">
      <div class="section-heading"><div><h2>导入会话</h2><span>{{ sqlImportStepLabel(importTask.step) }}</span></div><el-tag :type="tagType">{{ sqlImportStatusLabel(importTask.status) }}</el-tag></div>
      <el-alert v-if="importTask.error" type="error" :closable="false" show-icon :title="importTask.error" />
      <div v-if="operationError" class="operation-error">
        <el-alert :type="operationError.conflict ? 'warning' : 'error'" :closable="false" show-icon :title="operationError.conflict ? '资源编码或名称冲突' : '导入操作失败'" :description="operationError.message" />
        <div v-if="operationError.resource" class="conflict-resource">冲突资源：{{ operationError.resource.name || operationError.resource.code || operationError.resource.id }}</div>
        <details class="technical-details"><summary>查看排查信息</summary><dl><div><dt>导入会话</dt><dd>{{ importTask.importId || '—' }}</dd></div><div><dt>错误编号</dt><dd>{{ operationError.code || '—' }}</dd></div><div><dt>追踪编号</dt><dd>{{ operationError.traceId || '—' }}</dd></div></dl></details>
        <div class="error-actions"><el-button v-if="operationError.conflict && canEditMetadata" type="primary" @click="useNextCodeBatch">使用下一批编码并继续</el-button><el-button v-if="operationError.resource?.id" @click="openConflictResource">打开冲突资源</el-button></div>
      </div>
      <div v-if="preview" class="preview-summary"><span>解析到 {{ preview.factors.length }} 个因子</span><span v-if="preview.normalizedSql">已生成规范化 SQL</span></div>
      <div v-if="preview?.tables.length" class="block"><h3>表映射</h3><el-table :data="preview.tables" border><el-table-column prop="physicalTable" label="物理表" min-width="180" /><el-table-column label="映射" min-width="340"><template #default="{ row }"><el-select v-model="tableMappings[row.physicalTable]" :disabled="!canEditMetadata || !row.candidates.length" filterable :placeholder="mappingPlaceholder(row)"><el-option v-for="item in row.candidates" :key="item.viewMappingId" :value="item.viewMappingId" :label="`${item.domainCode} / ${item.semanticTableCode}`" /><el-option v-if="!row.candidates.length && tableMappings[row.physicalTable]" :value="tableMappings[row.physicalTable]" label="已由 SQL 解析自动确定" /></el-select><small v-if="!row.candidates.length" class="mapping-hint">{{ tableMappings[row.physicalTable] ? '当前映射已由 SQL 解析自动确定，无需选择。' : '后端未返回可选映射；请先完成该物理表的数据治理映射。' }}</small></template></el-table-column></el-table></div>
      <div v-if="preview?.diagnostics.length" class="block"><h3>解析诊断</h3><el-alert v-for="item in preview.diagnostics" :key="`${item.code}-${item.path}`" :type="item.severity === 'ERROR' ? 'error' : 'warning'" :closable="false" :title="item.message" :description="item.suggestion" /></div>
    </section>

    <template v-if="canEditMetadata">
      <section class="surface-card section"><div class="section-heading"><div><h2>2. 确认治理元数据</h2><span>确认后才能试算。</span></div></div><el-form label-position="top"><el-radio-group v-model="scope"><el-radio label="FACTORS_ONLY">仅创建因子</el-radio><el-radio label="FACTORS_AND_INDICATOR">创建因子及指标</el-radio></el-radio-group><el-form-item label="业务分类"><el-input v-model.trim="category" maxlength="64" /></el-form-item></el-form>
        <div class="factor-list">
          <div v-for="factor in factorMetadata" :key="factor.key" class="factor">
            <strong>{{ factor.key }}</strong><small>CTE 输出：{{ factorOutputAlias(factor.key) || '-' }}</small>
            <div class="factor-fields"><el-input v-model="factor.code" placeholder="因子编码（已按解析建议预填）" @input="factor.code = normalizeCode(factor.code)" /><el-input v-model.trim="factor.name" placeholder="因子名称（已按解析建议预填）" /><el-input v-model.trim="factor.description" placeholder="因子说明" /><el-select v-model="factor.missingRowPolicy" placeholder="缺行策略"><el-option label="保留空值" value="KEEP_NULL" /><el-option label="按零处理" value="ZERO" /></el-select><el-select v-model="factor.calculationMode" @change="onFactorModeChange(factor)"><el-option label="静态（全量一次计算）" value="STATIC" /><el-option label="时序（按周期计算）" value="TEMPORAL" /></el-select><div v-if="factor.calculationMode === 'TEMPORAL'" class="time-field-control"><el-select v-if="timeFieldOptions(factor).length" v-model="factor.timeField" filterable placeholder="确认时间字段"><el-option v-for="field in timeFieldOptions(factor)" :key="field.fieldReference" :label="timeFieldOptionLabel(field)" :value="field.fieldReference"><span>{{ timeFieldOptionLabel(field) }}</span></el-option></el-select><el-input v-else v-model.trim="factor.timeField" placeholder="请选择物理时间字段" readonly /><el-button @click="openTimeFieldSelector(factor)">浏览全部字段</el-button></div><small v-if="factor.calculationMode === 'TEMPORAL' && selectedTimeFieldOption(factor)" class="time-field-hint">{{ timeFieldOptionDescription(selectedTimeFieldOption(factor)) }}</small><small v-else-if="factor.calculationMode === 'TEMPORAL'" class="time-field-hint">候选字段不满足业务语义时，可从 SQL 涉及的物理表中选择；提交后仍由后端校验字段归属和时间格式。</small></div>
            <div class="parameter-header"><div><b>SQL 运行参数</b><small>参数编码必须与后端可识别的 SQL 参数一致；当前接口仅支持标量值。</small></div><el-tooltip content="添加运行参数"><el-button :icon="Plus" circle plain aria-label="添加运行参数" @click="addRuntimeParameter(factor)" /></el-tooltip></div>
            <div v-if="factor.parameters?.length" class="parameter-list">
              <div v-for="(parameter, index) in factor.parameters" :key="index" class="parameter-row"><el-input v-model.trim="parameter.code" placeholder="参数编码，如 deptCode" /><el-select v-model="parameter.type" aria-label="参数类型"><el-option v-for="type in parameterTypes" :key="type" :label="parameterTypeLabel(type)" :value="type" /></el-select><el-select v-model="parameter.parameterMode" aria-label="参数模式"><el-option label="临时重算" value="TEMPORARY" /><el-option label="结果维度" value="DIMENSION" /></el-select><el-checkbox v-model="parameter.required">必填</el-checkbox><el-tooltip content="删除参数"><el-button :icon="Delete" circle text type="danger" aria-label="删除参数" @click="removeRuntimeParameter(factor, index)" /></el-tooltip></div>
            </div>
          </div>
        </div>
      </section>
      <section v-if="scope === 'FACTORS_AND_INDICATOR'" class="surface-card section"><h2>指标信息</h2><el-form label-position="top"><div class="grid"><el-form-item label="指标编码"><el-input v-model="indicator.code" @input="indicator.code = normalizeCode(indicator.code)" /></el-form-item><el-form-item label="指标名称"><el-input v-model.trim="indicator.name" /></el-form-item></div><el-form-item label="指标说明"><el-input v-model.trim="indicator.description" type="textarea" /></el-form-item><el-form-item v-if="allTemporal" label="时间下钻"><el-switch v-model="indicator.timeDrillEnabled" active-text="启用" inactive-text="关闭" /></el-form-item><el-alert v-else-if="mixedModes" type="warning" :closable="false" title="当前因子同时包含静态与时序模式，不能创建同一个指标；请改为仅创建因子，或统一全部因子的计算模式。" /><el-alert v-else type="info" :closable="false" title="静态指标不支持时间下钻。" /></el-form></section>
      <section v-if="scope === 'FACTORS_AND_INDICATOR'" class="surface-card section">
        <h2>组合粒度与业务下钻</h2>
        <SqlImportGroupingFields v-model:dimension-grain="indicator.dimensionGrain" v-model:drill-paths="indicator.drillPaths" v-model:factors="factorMetadata" :drafts="preview.factors" :catalog="drillPathCatalog" :loading="drillPathLoading" :error="drillPathError" @reload="loadDrillPathCatalog" />
      </section>
      <section class="surface-card section"><h2>解析结果预览</h2><el-tabs><el-tab-pane v-for="factor in preview.factors" :key="factor.key" :label="factor.key"><JsonCodePreview :value="factor.dsl" :label="`${factor.key} 因子 DSL`" /></el-tab-pane><el-tab-pane label="指标公式"><JsonCodePreview :value="preview.formula?.template || {}" label="指标公式" /></el-tab-pane></el-tabs></section>
      <div class="action-bar"><el-button type="primary" :loading="metadataLoading" @click="submitMetadata">确认元数据并进入试算</el-button></div>
    </template>

    <section v-if="canTrial || isSucceeded" class="surface-card section"><div class="section-heading"><div><h2>{{ isSucceeded ? '运行条件与即时查询' : '3. 导入试算' }}</h2><span>{{ runtimeConditionHint }}</span></div><el-button v-if="canTrial" type="primary" :loading="trialLoading" @click="runTrial">发起试算</el-button><div v-else class="query-actions"><el-select v-if="publishedFactors.length" v-model="selectedFactorVersionId" placeholder="选择因子" aria-label="选择即时查询因子"><el-option v-for="factor in publishedFactors" :key="factor.factorVersionId" :label="factor.key || factor.factorCode || factor.factorVersionId" :value="factor.factorVersionId" /></el-select><el-button v-if="publishedFactors.length" :loading="runtimeQueryLoading" @click="runRuntimeQuery('FACTOR')">查询因子</el-button><el-button v-if="importTask.result?.indicatorVersionId" type="primary" :loading="runtimeQueryLoading" @click="runRuntimeQuery('INDICATOR')">查询指标</el-button></div></div>
      <el-alert v-if="parameterConflicts.length" class="condition-alert" type="error" :closable="false" show-icon :title="`存在不兼容的同名参数：${parameterConflicts.map(item => item.code).join('、')}`" description="试算请求只有一个 parameters 对象；同名参数在所有因子中的类型、必填性和模式必须一致。" />
      <div class="runtime-conditions">
        <div v-if="hasTemporalFactors" class="runtime-period">
          <span class="runtime-period__label">统计周期</span>
          <el-date-picker v-model="trialPeriod" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" start-placeholder="开始时间（包含）" end-placeholder="结束时间（不包含）" aria-label="试算统计周期" />
        </div>
        <div v-for="parameter in runtimeParameters" :key="parameter.code" class="runtime-field"><label><span>{{ parameter.code }}<em v-if="parameter.required">*</em></span><small>{{ parameterTypeLabel(parameter.type) }} · {{ parameter.parameterMode === 'TEMPORARY' ? '临时重算' : '结果维度' }}</small></label><el-select v-if="parameter.type === 'BOOLEAN'" v-model="runtimeParameterValues[parameter.code]" clearable placeholder="请选择"><el-option label="是" :value="true" /><el-option label="否" :value="false" /></el-select><el-input-number v-else-if="parameter.type === 'INTEGER'" v-model="runtimeParameterValues[parameter.code]" :precision="0" :controls="false" placeholder="请输入整数" /><el-input-number v-else-if="parameter.type === 'DECIMAL'" v-model="runtimeParameterValues[parameter.code]" :controls="false" placeholder="请输入数值" /><el-date-picker v-else-if="parameter.type === 'DATE'" v-model="runtimeParameterValues[parameter.code]" type="date" value-format="YYYY-MM-DD" placeholder="选择日期" /><el-date-picker v-else-if="parameter.type === 'DATETIME'" v-model="runtimeParameterValues[parameter.code]" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="选择日期时间" /><el-input v-else v-model="runtimeParameterValues[parameter.code]" clearable :placeholder="parameter.code.toLowerCase().includes('dept') ? '输入单个科室编码' : '请输入参数值'" /></div>
      </div>
      <el-alert v-if="runtimeParameters.some(item => item.code.toLowerCase().includes('dept'))" class="condition-alert" type="info" :closable="false" title="当前后端参数契约只支持单个标量科室编码；多科室选择需后端增加数组参数类型后再开放。" />
      <div v-if="runtimeQueryResult" class="runtime-result"><div class="result-summary"><el-tag :type="runtimeQueryResult.executionMode === 'AD_HOC_SOURCE' ? 'warning' : 'success'">{{ runtimeQueryResult.executionMode === 'AD_HOC_SOURCE' ? '按源数据计算' : '正式结果' }}</el-tag><span>参数快照：{{ JSON.stringify(runtimeQueryResult.parameterSnapshot || {}) }}</span></div><el-table :data="runtimeQueryResult.rows || []" border max-height="360" empty-text="当前条件没有结果"><el-table-column v-for="column in runtimeResultColumns" :key="column" :prop="column" :label="column" min-width="140"><template #default="{ row }">{{ formatRuntimeCell(row[column]) }}</template></el-table-column></el-table></div>
    </section>
    <section v-if="canFinalize" class="surface-card section"><h2>4. 试算成功</h2><el-alert type="success" :closable="false" title="试算成功，尚未创建和发布正式资源。请核对资源级诊断后确认发布。" /><ResourceTable :resources="importTask.resources" /><div class="action-bar"><el-button type="success" :loading="finalizeLoading" @click="finalizeImport">确认创建并发布</el-button></div></section>
    <section v-if="importTask?.resources.length && !canFinalize" class="surface-card section"><h2>资源状态</h2><ResourceTable :resources="importTask.resources" /></section>
    <section v-if="importTask?.status === 'FAILED' || importTask?.status === 'CLEANUP_FAILED'" class="surface-card section"><el-alert v-if="importTask.status === 'FAILED'" type="warning" :closable="false" title="重试会沿用原 SQL、原编码和原检查点；如果失败原因是 SQL、时间字段或编码错误，请放弃并清理，不要重试。" /><el-alert v-else type="error" :closable="false" title="半成品清理失败。请保留 importId、资源状态和 traceId 交由后端处理；不要复用本次编码。" /><div class="action-bar"><el-button type="primary" :loading="actionLoading" :disabled="importTask.status !== 'FAILED'" @click="retryImport">重试原任务</el-button><el-button type="danger" plain :loading="actionLoading" @click="abandonImport">放弃并清理</el-button></div></section>
    <section v-if="importTask?.status === 'ABANDONING'" class="surface-card section"><el-alert type="warning" :closable="false" show-icon title="正在清理未发布半成品，请等待状态变为 ABANDONED 后再开始新导入。" /></section>
    <section v-if="importTask?.status === 'ABANDONED'" class="surface-card section"><el-result icon="warning" title="导入已放弃，半成品清理已完成" sub-title="现在可以开始新的导入；如果相同编码仍冲突，请记录 importId 和 traceId，这是后端清理一致性问题。"><template #extra><el-button type="primary" @click="startNewImport">开始新的导入</el-button><el-button @click="router.push('/indicator')">返回指标目录</el-button></template></el-result></section>
    <section v-if="isSucceeded" class="surface-card section"><el-result icon="success" title="SQL 导入及发布已完成" sub-title="因子和指标已经由导入流程完成编译与发布；可在上方修改条件并即时查询。"><template #extra><el-button @click="router.push('/indicator')">返回指标目录</el-button><el-button v-if="importTask.result?.indicatorId" type="primary" @click="router.push(`/indicator/edit/${importTask.result.indicatorId}`)">查看指标</el-button><el-button v-if="importTask.result?.initializationBatchId" @click="router.push({ path: '/calc', query: { batchId: importTask.result.initializationBatchId } })">跟踪静态初始化批次</el-button></template></el-result><el-alert v-if="importTask.result?.initializationBatchId" :type="initializationStatus === 'SUCCEEDED' ? 'success' : initializationStatus === 'FAILED' ? 'error' : 'info'" :closable="false" show-icon :title="`初始化批次 ${importTask.result.initializationBatchId}：${initializationStatus ? sqlImportStatusLabel(initializationStatus) : '正在查询'}`" /></section>

    <el-dialog v-model="timeFieldDialogVisible" title="选择物理时间字段" width="760px" destroy-on-close>
      <el-alert type="info" :closable="false" show-icon title="这里展示 SQL 涉及物理表的全部字段。字符字段仍需后端通过源值画像验证为日期或时间。" />
      <el-input v-model="timeFieldSearch" class="time-field-search" clearable placeholder="搜索表名、字段名、类型或注释" />
      <el-table v-loading="timeFieldLoading" :data="filteredPhysicalTimeFields" height="390" row-key="fieldReference" highlight-current-row @row-dblclick="choosePhysicalTimeField">
        <el-table-column prop="physicalTable" label="物理表" min-width="150" show-overflow-tooltip />
        <el-table-column prop="columnName" label="字段" min-width="160" show-overflow-tooltip />
        <el-table-column prop="columnType" label="类型" width="120" />
        <el-table-column prop="comment" label="字段说明" min-width="180" show-overflow-tooltip />
        <el-table-column label="操作" width="90"><template #default="{ row }"><el-button type="primary" link @click="choosePhysicalTimeField(row)">选择</el-button></template></el-table-column>
      </el-table>
      <template #footer><el-button @click="timeFieldDialogVisible = false">取消</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { ElMessage } from '@/idmp/utils/message'
import { ArrowLeft, Delete, Plus } from '@element-plus/icons-vue'
import { useRoute, useRouter } from 'vue-router'
import PageHeader from '@/idmp/components/PageHeader.vue'
import JsonCodePreview from '@/idmp/components/JsonCodePreview.vue'
import SqlImportGroupingFields from '@/idmp/components/SqlImportGroupingFields.vue'
import { normalizeDimensionGrain, serializeDrillPaths, sqlImportGroupingFields, sqlImportGroupingFieldLabels, selectSqlDimensionBindings, validateSqlDimensionBindings } from '@/idmp/features/indicator/grouping'
import { SQL_RUNTIME_PARAMETER_TYPES, buildSqlImportCreatePayload, buildSqlImportMetadataPayload, buildSqlImportTrialPayload, buildSqlRuntimeQueryPayload, canFinalizeSqlImport, canSubmitSqlImportMetadata, canTrialSqlImport, collectSqlRuntimeParameters, mergeSqlFactorMetadata, nextSqlImportCode, normalizeSqlImportOperationError, normalizeSqlImportTask, shouldPollSqlImport, sqlImportResourceTypeLabel, sqlImportStatusLabel, sqlImportStepLabel, validateSqlRuntimeParameterSyntax } from '@/idmp/api/adapters/sqlImport'
import { abandonSqlImport, createSqlImport, fetchSqlImport, finalizeSqlImport, retrySqlImport, trialSqlImport, updateSqlImportMetadata } from '@/idmp/api/modules/sqlImports'
import { fetchCalcBatch } from '@/idmp/api/modules/calculation'
import { fetchSourceTableFields, fetchDrillPaths, fetchDrillPathVersion } from '@/idmp/api/modules/meta'
import { queryFactorVersion } from '@/idmp/api/modules/factors'
import { queryIndicatorVersion } from '@/idmp/api/modules/indicators'

const ResourceTable = { props: { resources: { type: Array, default: () => [] } }, setup: () => ({ statusLabel: sqlImportStatusLabel, resourceTypeLabel: sqlImportResourceTypeLabel }), template: '<el-table :data="resources" size="small"><el-table-column prop="key" label="资源"/><el-table-column label="类型"><template #default="{row}">{{ resourceTypeLabel(row.type) }}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{ row.published ? "已发布" : row.compiled ? "已编译" : statusLabel(row.trial?.status || "RUNNING") }}</template></el-table-column><el-table-column label="诊断"><template #default="{row}">{{ row.diagnostics?.map(x => x.message || x).join("；") || "—" }}</template></el-table-column></el-table>' }
const router = useRouter(); const route = useRoute(); const sql = ref(''); const importTask = ref(null); const factorMetadata = ref([]); const tableMappings = reactive({}); const scope = ref('FACTORS_AND_INDICATOR'); const category = ref(''); const trialPeriod = ref([])
const indicator = reactive({ code: '', name: '', description: '', timeDrillEnabled: true, formula: null, drillPaths: [], dimensionGrain: [] })
const drillPathCatalog = ref([]); const drillPathLoading = ref(false); const drillPathError = ref('')
async function loadDrillPathCatalog() {
  drillPathLoading.value = true; drillPathError.value = ''
  try {
    const paths = []
    for (let page = 1; ; page++) {
      const result = await fetchDrillPaths({ subjectType: 'INDICATOR_RESULT', page, size: 100 })
      const rows = result.records || []
      paths.push(...rows)
      if (!rows.length || paths.length >= Number(result.total || rows.length)) break
    }
    const ids = [...new Set(paths.filter(path => ['ORGANIZATION', 'DISEASE'].includes(path.pathCode)).map(path => path.currentPublishedVersionId).filter(Boolean))]
    const details = await Promise.all(ids.map(fetchDrillPathVersion))
    drillPathCatalog.value = details.filter(detail => detail.version?.publicationStatus === 'PUBLISHED' && detail.levels?.length)
  } catch (error) { drillPathError.value = error?.message || '下钻路径读取失败，请重试' }
  finally { drillPathLoading.value = false }
}
function metadataPayload() {
  const fields = scope.value === 'FACTORS_ONLY' ? [] : sqlImportGroupingFields(indicator.drillPaths, indicator.dimensionGrain, drillPathCatalog.value)
  return buildSqlImportMetadataPayload({ scope: scope.value, category: category.value, indicator, factors: factorMetadata.value.map(factor => ({ ...factor, dimensionBindings: selectSqlDimensionBindings(factor, fields) })) })
}
function validateGrouping() {
  if (scope.value !== 'FACTORS_AND_INDICATOR') return ''
  try {
    normalizeDimensionGrain(indicator.dimensionGrain)
    serializeDrillPaths(indicator.drillPaths)
    for (const path of indicator.drillPaths) {
      const definition = drillPathCatalog.value.find(item => String(item.version.id) === String(path.pathVersionId))
      if (!definition?.levels.some(level => level.levelCode === path.maxLevel)) return '下钻路径版本或层级已不可用，请刷新路径后重新选择'
    }
    const fields = sqlImportGroupingFields(indicator.drillPaths, indicator.dimensionGrain, drillPathCatalog.value)
    const labels = sqlImportGroupingFieldLabels(indicator.drillPaths, indicator.dimensionGrain, drillPathCatalog.value)
    const bindingError = validateSqlDimensionBindings(factorMetadata.value, preview.value?.factors || [], fields, labels)
    if (bindingError) return bindingError
    if (fields.length) {
      for (const draft of preview.value?.factors || []) {
        if (!draft.groupingSupported) return `因子 ${draft.key} 的 SQL 暂不支持组合粒度或业务下钻`
        const factor = factorMetadata.value.find(item => item.key === draft.key)
        for (const [code, binding] of Object.entries(selectSqlDimensionBindings(factor, fields))) {
          if (!draft.dimensionFieldOptions.some(field => field.fieldReference === binding)) return `因子 ${draft.key} 的 ${code} 映射字段不属于当前 SQL，请重新选择`
        }
      }
    }
    return ''
  } catch (error) { return error.message }
}
const operationError = ref(null); const createLoading = ref(false); const metadataLoading = ref(false); const trialLoading = ref(false); const finalizeLoading = ref(false); const actionLoading = ref(false); const initializationStatus = ref(''); let timer = null; let initializationTimer = null
const parameterTypes = SQL_RUNTIME_PARAMETER_TYPES; const runtimeParameterValues = reactive({}); const runtimeQueryLoading = ref(false); const runtimeQueryResult = ref(null); const selectedFactorVersionId = ref('')
const timeFieldDialogVisible = ref(false); const timeFieldLoading = ref(false); const timeFieldSearch = ref(''); const physicalTimeFields = ref([]); const activeTimeFieldFactor = ref(null)
const preview = computed(() => importTask.value?.preview || null); const canEditMetadata = computed(() => canSubmitSqlImportMetadata(importTask.value)); const canTrial = computed(() => canTrialSqlImport(importTask.value)); const canFinalize = computed(() => canFinalizeSqlImport(importTask.value)); const canStartNewImport = computed(() => ['ABANDONED', 'SUCCEEDED'].includes(String(importTask.value?.status || '').toUpperCase())); const hasTemporalFactors = computed(() => factorMetadata.value.some(x => x.calculationMode === 'TEMPORAL')); const allTemporal = computed(() => factorMetadata.value.length > 0 && factorMetadata.value.every(x => x.calculationMode === 'TEMPORAL')); const mixedModes = computed(() => hasTemporalFactors.value && factorMetadata.value.some(x => x.calculationMode === 'STATIC')); const tagType = computed(() => ({ SUCCEEDED: 'success', FAILED: 'danger', TRIAL_SUCCEEDED: 'success', READY_FOR_TRIAL: 'warning', AWAITING_METADATA: 'info', ABANDONED: 'info', CLEANUP_FAILED: 'danger' })[importTask.value?.status] || 'warning')
const filteredPhysicalTimeFields = computed(() => { const keyword = timeFieldSearch.value.trim().toLowerCase(); return keyword ? physicalTimeFields.value.filter(item => [item.physicalTable, item.columnName, item.columnType, item.comment].some(value => String(value || '').toLowerCase().includes(keyword))) : physicalTimeFields.value })
const runtimeParameters = computed(() => collectSqlRuntimeParameters(factorMetadata.value)); const parameterConflicts = computed(() => runtimeParameters.value.filter(item => item.conflict)); const isSucceeded = computed(() => importTask.value?.status === 'SUCCEEDED'); const publishedFactors = computed(() => importTask.value?.result?.factors || []); const runtimeResultColumns = computed(() => [...new Set((runtimeQueryResult.value?.rows || []).flatMap(row => Object.keys(row || {})))]); const runtimeConditionHint = computed(() => isSucceeded.value ? '修改日期或业务参数后即时查询；临时参数会触发源数据重算。' : (hasTemporalFactors.value ? '选择半开时间区间并填写 SQL 运行参数。' : '填写 SQL 运行参数；静态导入不传统计周期。'))
function key(prefix) { return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}` }; function normalizeCode(value) { return String(value || '').toUpperCase().replace(/[^A-Z0-9_]/g, '') }; function factorOutputAlias(id) { return preview.value?.factors.find(x => x.key === id)?.outputAlias }; function timeFieldOptions(factor) { return preview.value?.factors.find(x => x.key === factor.key)?.timeFieldOptions || [] }; function mappingPlaceholder(row) { return row.candidates.length ? '请选择语义映射' : (tableMappings[row.physicalTable] ? '已自动确定' : '后端未返回候选映射') }
function selectedTimeFieldOption(factor) { return timeFieldOptions(factor).find(item => item.fieldReference === factor.timeField) }
function timeFieldOptionLabel(option) { return `${option.recommended ? '推荐 · ' : ''}${option.fieldReference}${option.columnType ? ` · ${option.columnType}` : ''}${option.comment ? ` · ${option.comment}` : ''}` }
function timeFieldOptionDescription(option) { const reasons = option.recommendationReasons?.join('；'); return reasons || (option.recommended ? '后端推荐的时间字段，请确认符合本次统计口径。' : '提交后由后端校验字段归属和时间格式。') }
function parameterTypeLabel(type) { return ({ STRING: '文本', INTEGER: '整数', DECIMAL: '小数', BOOLEAN: '布尔', DATE: '日期', DATETIME: '日期时间' })[type] || type }
function addRuntimeParameter(factor) { if (!Array.isArray(factor.parameters)) factor.parameters = []; factor.parameters.push({ code: '', type: 'STRING', required: false, parameterMode: 'TEMPORARY' }) }
function removeRuntimeParameter(factor, index) { factor.parameters.splice(index, 1) }
function validateRuntimeDeclarations() { for (const factor of factorMetadata.value) { const codes = new Set(); for (const parameter of factor.parameters || []) { if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(parameter.code || '')) return `因子 ${factor.key} 的参数编码必须以字母开头，且只能包含字母、数字和下划线`; if (codes.has(parameter.code)) return `因子 ${factor.key} 存在重复参数 ${parameter.code}`; codes.add(parameter.code) } } if (parameterConflicts.value.length) return `同名参数声明不一致：${parameterConflicts.value.map(item => item.code).join('、')}`; return '' }
function validateRuntimeValues() { const missing = runtimeParameters.value.filter(item => item.required && (runtimeParameterValues[item.code] === undefined || runtimeParameterValues[item.code] === null || runtimeParameterValues[item.code] === '')).map(item => item.code); return missing.length ? `请填写必填参数：${missing.join('、')}` : '' }
function formatRuntimeCell(value) { return value && typeof value === 'object' ? JSON.stringify(value) : (value ?? '—') }
async function openTimeFieldSelector(factor) { activeTimeFieldFactor.value = factor; timeFieldSearch.value = ''; timeFieldDialogVisible.value = true; timeFieldLoading.value = true; physicalTimeFields.value = []; const candidateTables = timeFieldOptions(factor).map(item => item.physicalTable); const tables = [...new Set([...candidateTables, ...(preview.value?.tables || []).map(item => item.physicalTable)].filter(Boolean))]; if (!tables.length) { timeFieldLoading.value = false; return ElMessage.warning('解析结果未返回可查询的物理表') } const results = await Promise.allSettled(tables.map(async physicalTable => ({ physicalTable, fields: await fetchSourceTableFields(physicalTable) }))); physicalTimeFields.value = results.flatMap(result => result.status === 'fulfilled' ? (Array.isArray(result.value.fields) ? result.value.fields : []).map(field => ({ physicalTable: result.value.physicalTable, columnName: String(field.columnName || ''), columnType: String(field.columnType || ''), comment: String(field.comment || ''), fieldReference: `${result.value.physicalTable}.${field.columnName}` })) : []).filter(item => item.columnName); timeFieldLoading.value = false; if (!physicalTimeFields.value.length) ElMessage.warning('未能读取物理表字段，请检查数据源权限后重试') }
function choosePhysicalTimeField(field) { if (!activeTimeFieldFactor.value) return; activeTimeFieldFactor.value.timeField = field.fieldReference; timeFieldDialogVisible.value = false; ElMessage.success(`已选择 ${field.fieldReference}`) }
function onFactorModeChange(factor) { if (factor.calculationMode === 'STATIC') factor.timeField = ''; else if (!factor.timeField) factor.timeField = timeFieldOptions(factor).find(item => item.recommended)?.fieldReference || '' }
function accept(payload) {
  const task = normalizeSqlImportTask(payload); importTask.value = task
  if (task.importId) router.replace({ query: { ...route.query, importId: task.importId } })
  if (task.preview?.factors?.length && !factorMetadata.value.length) {
    factorMetadata.value = mergeSqlFactorMetadata(task.metadata?.factors || [], task.preview.factors)
    task.preview.tables.forEach(x => { if (x.selectedViewMappingId) tableMappings[x.physicalTable] = x.selectedViewMappingId })
    if (task.metadata) {
      scope.value = task.metadata.scope; category.value = task.metadata.category || ''
      Object.assign(indicator, { code: task.metadata.indicatorCode || '', name: task.metadata.indicatorName || '', description: task.metadata.indicatorDescription || '', timeDrillEnabled: task.metadata.timeDrillEnabled !== false, formula: task.metadata.formula, drillPaths: task.metadata.drillPaths, dimensionGrain: task.metadata.dimensionGrain })
    }
  }
  if (!selectedFactorVersionId.value && task.result?.factors?.length) selectedFactorVersionId.value = String(task.result.factors[0].factorVersionId || '')
  schedule(); if (task.status === 'SUCCEEDED' && task.result?.initializationBatchId) scheduleInitializationPoll(task.result.initializationBatchId)
}
function schedule() { clearTimeout(timer); if (shouldPollSqlImport(importTask.value)) timer = setTimeout(refresh, 1500) }
async function refresh() { if (!importTask.value?.importId) return; try { accept(await fetchSqlImport(importTask.value.importId)) } catch (e) { captureOperationError(e, '导入状态读取失败，请稍后重试') } }
async function createImport() { const syntaxMessage = validateSqlRuntimeParameterSyntax(sql.value); if (syntaxMessage) return ElMessage.warning({ message: syntaxMessage, duration: 8000, showClose: true }); operationError.value = null; createLoading.value = true; try { accept(await createSqlImport(buildSqlImportCreatePayload({ sql: sql.value, tableMappings }), key('sql-import'))); ElMessage.success('SQL 已解析，请确认治理元数据') } catch (e) { captureOperationError(e, 'SQL 解析失败') } finally { createLoading.value = false } }
function validateMetadata() { if (!factorMetadata.value.every(x => x.code && x.name && (x.calculationMode !== 'TEMPORAL' || x.timeField))) return '请补全因子编码、名称和时序因子的时间字段'; const parameterMessage = validateRuntimeDeclarations(); if (parameterMessage) return parameterMessage; if (scope.value === 'FACTORS_AND_INDICATOR') { if (!indicator.code || !indicator.name) return '请填写指标编码和名称'; const modes = new Set(factorMetadata.value.map(x => x.calculationMode)); if (modes.size !== 1) return '创建指标时，全部因子必须使用相同计算模式'; if (!hasFormula(preview.value?.formula?.template)) return '解析结果没有可提交的指标公式，请调整 SQL 后重新解析，或改为仅创建因子' } return validateGrouping() }
async function submitMetadata() { const message = validateMetadata(); if (message) return ElMessage.warning(message); operationError.value = null; metadataLoading.value = true; try { indicator.formula = preview.value?.formula?.template || {}; if (!allTemporal.value) indicator.timeDrillEnabled = false; let activeImportId = importTask.value.importId; if (needsMappedReparse()) { const previousImportId = activeImportId; const previousFactors = factorMetadata.value; const mappedTask = await createSqlImport(buildSqlImportCreatePayload({ sql: sql.value || preview.value?.normalizedSql, tableMappings }), key('sql-import-mapped')); accept(mappedTask); activeImportId = importTask.value.importId; if (!activeImportId) throw new Error('映射重解析未返回新的导入会话 ID'); factorMetadata.value = mergeSqlFactorMetadata(previousFactors, preview.value?.factors || []); indicator.formula = preview.value?.formula?.template || {}; const mappedValidation = validateMetadata(); if (mappedValidation) throw new Error(`映射重解析后需要重新确认：${mappedValidation}`); void abandonSqlImport(previousImportId, '已按人工确认的表映射重新创建导入会话', key('sql-reparse-cleanup')).catch(() => {}); } accept(await updateSqlImportMetadata(activeImportId, metadataPayload())); ElMessage.success('元数据已确认，可发起试算') } catch (e) { captureOperationError(e, '元数据提交失败') } finally { metadataLoading.value = false } }
async function runTrial() { const valueMessage = validateRuntimeValues(); if (valueMessage) return ElMessage.warning(valueMessage); const payload = buildSqlImportTrialPayload(factorMetadata.value, trialPeriod.value, runtimeParameterValues); if (hasTemporalFactors.value && (!payload.periodStart || !payload.periodEnd)) return ElMessage.warning('请选择完整试算周期'); operationError.value = null; trialLoading.value = true; try { accept(await trialSqlImport(importTask.value.importId, payload, key('sql-trial'))) } catch (e) { captureOperationError(e, '导入试算失败') } finally { trialLoading.value = false } }
